    async def fetch_permissions(self, params={}) -> List[str]:
        accounts = await self.fetch_accounts(params)
        rights: List[str] = []
        if len(accounts) == 0:
            return rights
        firstAccount = accounts[0]
        rawInfo = self.safe_dict(firstAccount, 'info')
        rawPerm = rawInfo['perm']
        permTxt = rawPerm.lower() if isinstance(rawPerm, str) else ''
        permSegments = permTxt.split(',')
        restrictions = []
        for segIdx in range(0, len(permSegments)):
            segment = permSegments[segIdx]
            restrictions.append(segment.strip().lower())
        if self.in_array('read_only', restrictions):
            rights.append('reading')
        if self.in_array('trade', restrictions):
            rights.append('spotTrading')
            rights.append('marginTrading')
            rights.append('futuresTrading')
        if self.in_array('withdraw', restrictions):
            rights.append('withdrawals')
        return rights

