    def parse_order(self, order: dict, market: Market = None) -> Order:
        # override the standard parseOrder to apply OctoBot's OKXCCXTAdapter._adapt_order_type:
        # when ccxt did not flag the order basic market/limit order, infer stop_loss, take_profit,
        # unsupported OCO, or unknown from OKX info fields and trigger price vs last price and side
        parsed = super(ob_myokx, self).parse_order(order, market)
        type = self.safe_string_lower(parsed, 'type')
        if type != 'market' and type != 'limit':
            info = self.safe_dict(parsed, 'info', {})
            triggerPrice = self.safe_number(parsed, 'triggerPrice')
            lastPrice = self.safe_number(info, 'last')
            slTrigger = self.safe_number(info, 'slTriggerPx')
            tpTrigger = self.safe_number(info, 'tpTriggerPx')
            updated = 'unknown'
            if slTrigger is not None and tpTrigger is not None:
                # OCO order, unsupported yet
                self.log('ob_myokx.parseOrder', 'Unsupported OKX OCO(stop loss & take profit in a single order): ' + self.json(parsed))
                updated = 'unsupported'
            elif slTrigger is not None:
                updated = 'stop_loss'
            elif tpTrigger is not None:
                updated = 'take_profit'
            elif lastPrice is not None and triggerPrice is not None:
                side = self.safe_string_lower(parsed, 'side')
                if side == 'buy':
                    # trigger stop loss buy when price goes below trigger, untriggered when last price is above
                    updated = 'stop_loss' if (lastPrice > triggerPrice) else 'take_profit'
                else:
                    # trigger take profit sell when price goes above trigger, untriggered when last price is below
                    updated = 'take_profit' if (lastPrice < triggerPrice) else 'stop_loss'
            else:
                self.log('ob_myokx.parseOrder', 'Unknown ob_myokx order type, order: ' + self.json(parsed))
            # stop loss and take profits are not tagged by ccxt, force it
            parsed['type'] = updated
        return parsed
